import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int finish = Integer.parseInt(st.nextToken()), n = Integer.parseInt(st.nextToken());
        int[] s = new int[n];
        for (int i = 0; i < n; i++) s[i] = Integer.parseInt(st.nextToken());
        Arrays.sort(s);
        int pos = 0, total = 0, i = 0;
        while (pos < finish) {
            while (i < n && s[i] < pos) i++;
            if (i == n) break;
            int x = s[i++], reached = Math.min(finish, x + 10);
            total += reached - x;
            pos = reached;
        }
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	finish, n := next(), next()
	s := make([]int, n)
	for i := range s {
		s[i] = next()
	}
	sort.Ints(s)
	pos, total, i := 0, 0, 0
	for pos < finish {
		for i < n && s[i] < pos {
			i++
		}
		if i == n {
			break
		}
		x := s[i]
		i++
		reached := min(finish, x+10)
		total += reached - x
		pos = reached
	}
	fmt.Println(total)
}
